**`CheckoutPage.tsx`**
```tsx
import React, { useMemo, useState } from 'react';
import './CheckoutPage.css';
import { CartItem, CheckoutPageProps, DeliveryAddress } from './CheckoutPage.types';

const EMPTY_ADDRESS: DeliveryAddress = {
  fullName: '',
  street: '',
  city: '',
  postalCode: '',
  country: '',
  phone: '',
};

type FieldErrors = Partial<Record<keyof DeliveryAddress, string>>;

function formatMoney(amount: number, currency: string): string {
  return new Intl.NumberFormat(undefined, {
    style: 'currency',
    currency,
  }).format(amount);
}

function validateAddress(address: DeliveryAddress): FieldErrors {
  const errors: FieldErrors = {};

  if (!address.fullName.trim()) errors.fullName = 'Full name is required.';
  if (!address.street.trim()) errors.street = 'Street address is required.';
  if (!address.city.trim()) errors.city = 'City is required.';
  if (!address.postalCode.trim()) {
    errors.postalCode = 'Postal code is required.';
  } else if (!/^[A-Za-z0-9\- ]{3,10}$/.test(address.postalCode.trim())) {
    errors.postalCode = 'Enter a valid postal code.';
  }
  if (!address.country.trim()) errors.country = 'Country is required.';
  if (!address.phone.trim()) {
    errors.phone = 'Phone number is required.';
  } else if (!/^[+\d][\d\s\-()]{6,}$/.test(address.phone.trim())) {
    errors.phone = 'Enter a valid phone number.';
  }

  return errors;
}

const CartLineItem: React.FC<{ item: CartItem; currency: string }> = ({ item, currency }) => (
  <li className="cart-line-item">
    <div className="cart-line-item__image">
      {item.imageUrl ? (
        <img src={item.imageUrl} alt={item.name} />
      ) : (
        <div className="cart-line-item__image-placeholder" aria-hidden="true" />
      )}
    </div>
    <div className="cart-line-item__info">
      <span className="cart-line-item__name">{item.name}</span>
      <span className="cart-line-item__qty">Qty: {item.quantity}</span>
    </div>
    <div className="cart-line-item__price">
      {formatMoney(item.unitPrice * item.quantity, currency)}
    </div>
  </li>
);

export const CheckoutPage: React.FC<CheckoutPageProps> = ({
  items,
  currency = 'USD',
  shippingCost = 0,
  onBackToCart,
  onPay,
}) => {
  const [address, setAddress] = useState<DeliveryAddress>(EMPTY_ADDRESS);
  const [errors, setErrors] = useState<FieldErrors>({});
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [submitError, setSubmitError] = useState<string | null>(null);

  const subtotal = useMemo(
    () => items.reduce((sum, item) => sum + item.unitPrice * item.quantity, 0),
    [items],
  );
  const total = subtotal + shippingCost;
  const isCartEmpty = items.length === 0;

  const handleFieldChange = (field: keyof DeliveryAddress) => (
    event: React.ChangeEvent<HTMLInputElement>,
  ) => {
    setAddress((prev) => ({ ...prev, [field]: event.target.value }));
    setErrors((prev) => ({ ...prev, [field]: undefined }));
  };

  const handleSubmit = async (event: React.FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    setSubmitError(null);

    const validationErrors = validateAddress(address);
    setErrors(validationErrors);
    if (Object.keys(validationErrors).length > 0 || isCartEmpty) {
      return;
    }

    setIsSubmitting(true);
    try {
      await onPay(address);
    } catch {
      setSubmitError('Payment could not be processed. Please try again.');
    } finally {
      setIsSubmitting(false);
    }
  };

  return (
    <div className="checkout-page">
      <div className="checkout-page__header">
        <button
          type="button"
          className="checkout-page__back-button"
          onClick={onBackToCart}
        >
          &larr; Back to cart
        </button>
        <h1 className="checkout-page__title">Checkout</h1>
      </div>

      <div className="checkout-page__content">
        <section className="checkout-section" aria-labelledby="order-summary-heading">
          <h2 id="order-summary-heading" className="checkout-section__heading">
            Order summary
          </h2>

          {isCartEmpty ? (
            <p className="checkout-page__empty">Your cart is empty.</p>
          ) : (
            <ul className="cart-line-item-list">
              {items.map((item) => (
                <CartLineItem key={item.id} item={item} currency={currency} />
              ))}
            </ul>
          )}

          <dl className="order-totals">
            <div className="order-totals__row">
              <dt>Subtotal</dt>
              <dd>{formatMoney(subtotal, currency)}</dd>
            </div>
            <div className="order-totals__row">
              <dt>Shipping</dt>
              <dd>{shippingCost === 0 ? 'Free' : formatMoney(shippingCost, currency)}</dd>
            </div>
            <div className="order-totals__row order-totals__row--total">
              <dt>Total</dt>
              <dd>{formatMoney(total, currency)}</dd>
            </div>
          </dl>
        </section>

        <section className="checkout-section" aria-labelledby="delivery-address-heading">
          <h2 id="delivery-address-heading" className="checkout-section__heading">
            Delivery address
          </h2>

          <form className="address-form" onSubmit={handleSubmit} noValidate>
            <div className="form-field">
              <label htmlFor="fullName">Full name</label>
              <input
                id="fullName"
                type="text"
                autoComplete="name"
                value={address.fullName}
                onChange={handleFieldChange('fullName')}
                aria-invalid={Boolean(errors.fullName)}
                aria-describedby={errors.fullName ? 'fullName-error' : undefined}
              />
              {errors.fullName && (
                <span id="fullName-error" className="form-field__error" role="alert">
                  {errors.fullName}
                </span>
              )}
            </div>

            <div className="form-field">
              <label htmlFor="street">Street address</label>
              <input
                id="street"
                type="text"
                autoComplete="street-address"
                value={address.street}
                onChange={handleFieldChange('street')}
                aria-invalid={Boolean(errors.street)}
                aria-describedby={errors.street ? 'street-error' : undefined}
              />
              {errors.street && (
                <span id="street-error" className="form-field__error" role="alert">
                  {errors.street}
                </span>
              )}
            </div>

            <div className="form-row">
              <div className="form-field">
                <label htmlFor="city">City</label>
                <input
                  id="city"
                  type="text"
                  autoComplete="address-level2"
                  value={address.city}
                  onChange={handleFieldChange('city')}
                  aria-invalid={Boolean(errors.city)}
                  aria-describedby={errors.city ? 'city-error' : undefined}
                />
                {errors.city && (
                  <span id="city-error" className="form-field__error" role="alert">
                    {errors.city}
                  </span>
                )}
              </div>

              <div className="form-field">
                <label htmlFor="postalCode">Postal code</label>
                <input
                  id="postalCode"
                  type="text"
                  autoComplete="postal-code"
                  value={address.postalCode}
                  onChange={handleFieldChange('postalCode')}
                  aria-invalid={Boolean(errors.postalCode)}
                  aria-describedby={errors.postalCode ? 'postalCode-error' : undefined}
                />
                {errors.postalCode && (
                  <span id="postalCode-error" className="form-field__error" role="alert">
                    {errors.postalCode}
                  </span>
                )}
              </div>
            </div>

            <div className="form-field">
              <label htmlFor="country">Country</label>
              <input
                id="country"
                type="text"
                autoComplete="country-name"
                value={address.country}
                onChange={handleFieldChange('country')}
                aria-invalid={Boolean(errors.country)}
                aria-describedby={errors.country ? 'country-error' : undefined}
              />
              {errors.country && (
                <span id="country-error" className="form-field__error" role="alert">
                  {errors.country}
                </span>
              )}
            </div>

            <div className="form-field">
              <label htmlFor="phone">Phone number</label>
              <input
                id="phone"
                type="tel"
                autoComplete="tel"
                value={address.phone}
                onChange={handleFieldChange('phone')}
                aria-invalid={Boolean(errors.phone)}
                aria-describedby={errors.phone ? 'phone-error' : undefined}
              />
              {errors.phone && (
                <span id="phone-error" className="form-field__error" role="alert">
                  {errors.phone}
                </span>
              )}
            </div>

            {submitError && (
              <p className="address-form__submit-error" role="alert">
                {submitError}
              </p>
            )}

            <div className="checkout-page__actions">
              <button
                type="button"
                className="button button--secondary"
                onClick={onBackToCart}
                disabled={isSubmitting}
              >
                Back to cart
              </button>
              <button
                type="submit"
                className="button button--primary"
                disabled={isSubmitting || isCartEmpty}
              >
                {isSubmitting ? 'Processing…' : `Pay ${formatMoney(total, currency)}`}
              </button>
            </div>
          </form>
        </section>
      </div>
    </div>
  );
};

export default CheckoutPage;
```

